const cardStyle = {
  background: "#ffffff",
  border: "1px solid #d1d5db",
  borderRadius: 12,
  padding: "12px 14px",
  marginBottom: 8,
};

function SectionLabel({ children, mt }) {
  return (
    <div style={{ fontSize: 11, fontWeight: 700, color: "#6b7280", letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 8, marginTop: mt || 0 }}>
      {children}
    </div>
  );
}

function DataRow({ k, v, last }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", borderBottom: last ? "none" : "1px solid #f3f4f6" }}>
      <span style={{ fontSize: 12, color: "#374151", flex: 1, paddingRight: 8 }}>{k}</span>
      <span style={{ fontSize: 12, fontWeight: 700, color: "#111827", textAlign: "right", maxWidth: "52%" }}>{v}</span>
    </div>
  );
}

